select energy_manager.load_cards($cards$[
{"id":"p3-044","paper":3,"topic":"Compressed air","kind":"problem","front":"In a pump-up test, the receiver plus piping volume is 8.4 m³. With the compressor running and all users isolated, pressure rises from 2.0 to 8.0 bar(g) in 3.5 minutes. Atmospheric pressure is 1.013 bar(a). Estimate the FAD. If rated capacity is 16 m³/min, what is the capacity shortfall?","back":"FAD ≈ 14.2 Nm³/min; shortfall ≈ 11% below rated.","explain":"The pump-up test treats compression into the receiver as isothermal: free air delivered = (P2 − P1)/P0 × V ÷ T. If the compressed-air temperature differs from ambient, multiply by (273 + t_ambient)/(273 + t_air). A large shortfall points to worn valves or rings or a fouled intake filter.","steps":[{"prompt":"Find the pressure rise.","answer":"P2 − P1 = 8.0 − 2.0 = 6.0 bar","explain":"Gauge readings can be used directly because only the difference matters."},{"prompt":"Apply the pump-up formula.","answer":"Q = (6.0/1.013) × 8.4 / 3.5","explain":"Q = (P2 − P1)/P0 × V/T, with V in m³ and T in min."},{"prompt":"Calculate the FAD.","answer":"5.923 × 2.4 ≈ 14.2 Nm³/min","explain":"Free air at atmospheric conditions."},{"prompt":"Compare with the rated capacity.","answer":"(16 − 14.2)/16 ≈ 11% shortfall","explain":"Volumetric efficiency has dropped; inspect the compressor."}],"flash":false,"source":"syllabus","order":3043},
{"id":"p3-045","paper":3,"topic":"Compressed air","kind":"problem","front":"With all users closed, a 20 m³/min compressor loads for 12 s and unloads for 36 s on average. Load power is 110 kW. Estimate the leakage, the percentage leakage, and the annual energy lost (8000 h/yr, neglecting unload power).","back":"Leakage = 5 m³/min (25% of capacity); ≈ 27.5 kW wasted; ≈ 2,20,000 kWh/yr.","explain":"With no consumption, the compressor's loaded time only replaces leaked air, so leak flow = FAD × on-time fraction. Treating the leak as an equal share of loaded running gives the wasted power. Unload power, typically 25–35% of load power for screw units, adds further waste.","steps":[{"prompt":"Find the loaded-time fraction.","answer":"T/(T + t) = 12/(12 + 36) = 0.25","explain":"On-time fraction of the cycle."},{"prompt":"Find the leakage flow.","answer":"20 × 0.25 = 5 m³/min","explain":"Leakage = FAD × T/(T + t)."},{"prompt":"Find the percentage leakage.","answer":"5/20 = 25%","explain":"Far above good practice (below about 10%)."},{"prompt":"Find the power and energy wasted.","answer":"110 × 0.25 = 27.5 kW; × 8000 h = 2,20,000 kWh/yr","explain":"The loaded power share serves only the leaks."}],"flash":false,"source":"BEE 2024 P3 Q22 (extended)","order":3044},
{"id":"p3-046","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"How much cooling is 1 ton of refrigeration (TR)?","back":"1 TR = 3024 kcal/h = 3.517 kW = 12,000 Btu/h.","explain":"It is the heat needed to melt 1 short ton of ice in 24 hours. Example: 27,216 kcal/h ÷ 3024 = 9 TR. In chilled-water systems, TR = flow (kg/h) × ΔT (°C) ÷ 3024.","flash":true,"source":"BEE 2025 P3 Q50","order":3045},
{"id":"p3-047","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"How are COP and kW/TR related?","back":"COP = cooling output ÷ power input (same units); kW/TR = 3.517 ÷ COP.","explain":"For example, a chiller providing 100 kW of cooling at COP 4 draws 25 kW. COP 5.86 ≈ 0.6 kW/TR. A lower kW/TR is better. Energy Efficiency Ratio (EER) is often quoted interchangeably with COP in Indian practice (both are dimensionless ratios, though EER can also be in Btu/Wh).","flash":true,"source":"BEE 2024 P3 Q49","order":3046},
{"id":"p3-048","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"What happens to the refrigerant in each component of a vapour compression cycle?","back":"Evaporator: absorbs heat; liquid evaporates at low pressure. Compressor: raises pressure and temperature. Condenser: rejects heat; vapour condenses to liquid. Expansion valve: throttles, dropping pressure and temperature at constant enthalpy.","explain":"Enthalpy changes across the compressor, condenser and evaporator, but expansion is (ideally) isenthalpic. In an ideal system the refrigerant temperature increases only in the compressor. Total heat rejected in the condenser = refrigeration effect + compressor work.","flash":false,"source":"BEE 2024 P3 Q45-46 / BEE 2025 P3 Q14, Q41","order":3047},
{"id":"p3-049","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"In a LiBr–water vapour absorption machine (VAM), which fluid is the refrigerant and which is the absorbent?","back":"Water is the refrigerant; lithium bromide is the absorbent.","explain":"Ammonia–water VAMs use ammonia as refrigerant and water as absorbent. Ammonia is the refrigerant common to both vapour compression and absorption systems. VAMs are driven by heat (steam, hot water, exhaust) with only small pump power, which makes them attractive where waste heat is available.","flash":false,"source":"BEE 2024 P3 Q47 / BEE 2025 P3 Q8","order":3048},
{"id":"p3-050","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"What is the effect of raising the chilled water leaving temperature (or evaporator temperature)?","back":"It raises chiller efficiency (higher COP, lower kW/TR). About 3% compressor power is saved per 1°C rise in evaporator temperature.","explain":"A higher evaporator temperature means higher suction pressure and a lower compression ratio, so less work per TR. Set the chilled water no colder than the process or comfort load needs. Likewise, a lower condensing temperature (cooler, clean condenser water) improves COP.","flash":true,"source":"BEE 2024 P3 Q48 / BEE 2025 P3 Q33","order":3049},
{"id":"p3-051","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"How does scale or fouling in condenser tubes affect a chiller?","back":"It reduces heat transfer, raises condensing temperature and pressure, and increases compressor energy use.","explain":"Fouling adds thermal resistance, so the refrigerant must condense at a higher temperature to reject the same heat. Watch the condenser approach (refrigerant condensing temperature − leaving water temperature). Tube cleaning and good cooling-water treatment restore performance.","flash":false,"source":"BEE 2025 P3 Q26","order":3050},
{"id":"p3-052","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"Which rejects more heat per TR to the cooling tower: a vapour compression chiller or a VAM?","back":"A VAM rejects much more, typically about 1.6–2 times as much, because it rejects both the refrigeration load and the driving heat input (low COP of about 0.7–1.3).","explain":"Vapour compression chiller: heat rejected = 3024 + kW/TR × 860 kcal/h per TR (e.g. 0.6 kW/TR gives 3540 kcal/h per TR). VAM: 3024 + 3024/COP. So VAMs need larger cooling towers and more pumping. That must enter any economic comparison along with the cost of steam versus power.","flash":false,"source":"BEE 2025 P3 S-6 / BEE 2024 P3 L5","order":3051},
{"id":"p3-053","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"If the dew point temperature equals the dry bulb temperature, what is the relative humidity?","back":"100%: the air is saturated.","explain":"At saturation, dry bulb = wet bulb = dew point. The wider the gap between dry bulb and wet bulb, the drier the air and the greater the potential for evaporative cooling.","flash":false,"source":"BEE 2025 P3 Q4","order":3052},
{"id":"p3-054","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"During evaporative cooling (air washer), what happens to dry bulb temperature, humidity ratio and enthalpy?","back":"Dry bulb falls, humidity ratio rises, and enthalpy stays about constant (it follows the wet bulb line).","explain":"Sensible heat in the air is converted to latent heat of the evaporated water, so total heat is essentially unchanged. Evaporative cooling works best in hot, dry climates.","flash":false,"source":"BEE 2025 P3 Q16","order":3053},
{"id":"p3-055","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"What does an air-side economiser do in an HVAC system?","back":"It uses cool outdoor air for 'free cooling' when outdoor conditions are favourable, reducing mechanical refrigeration.","explain":"Dampers increase outdoor air intake when its enthalpy or temperature is below that of return air. Water-side economisers similarly use cooling-tower water to pre-cool chilled water in cold weather.","flash":false,"source":"BEE 2024 P3 Q16","order":3054},
{"id":"p3-056","paper":3,"topic":"Refrigeration & HVAC","kind":"problem","front":"A chiller cools 100 m³/h of water from 12°C to 7°C. Compressor input is 150 kW. Find the cooling load in TR, kW/TR and COP. If the condenser water ΔT is 5°C, what condenser water flow is needed?","back":"≈ 165.3 TR; 0.907 kW/TR; COP ≈ 3.88; condenser water ≈ 125.8 m³/h.","explain":"Chilled-water TR uses m·cp·ΔT. The condenser must reject the refrigeration effect plus the compressor work (kW × 860 kcal/kWh), which is why condenser flow exceeds chilled water flow at the same ΔT. These are the standard steps of a chiller performance assessment.","steps":[{"prompt":"Find the refrigeration effect.","answer":"100,000 kg/h × 1 × (12 − 7) = 5,00,000 kcal/h","explain":"Q = m·cp·ΔT, with cp of water = 1 kcal/kg°C."},{"prompt":"Convert to TR.","answer":"5,00,000 / 3024 = 165.3 TR","explain":"1 TR = 3024 kcal/h."},{"prompt":"Find kW/TR.","answer":"150 / 165.3 = 0.907 kW/TR","explain":"Specific power consumption."},{"prompt":"Find the COP.","answer":"(165.3 × 3.517) / 150 = 581.5/150 ≈ 3.88","explain":"COP = cooling kW / input kW = 3.517/(kW/TR)."},{"prompt":"Find the condenser heat and water flow.","answer":"5,00,000 + 150 × 860 = 6,29,000 kcal/h; flow = 6,29,000/(1000 × 5) ≈ 125.8 m³/h","explain":"Heat rejected = cooling + work."}],"flash":false,"source":"BEE 2025 P3 S-6 (similar)","order":3055},
{"id":"p3-057","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What is the Energy Performance Index (EPI) of a building, and what is its unit?","back":"EPI = total annual energy consumption ÷ built-up area, in kWh/m²/year.","explain":"BEE star ratings for buildings use EPI bands; a lower EPI earns more stars. Use the built-up area (not carpet area) unless the rating scheme specifies otherwise. Total consumption includes grid plus DG/captive electricity.","flash":false,"source":"BEE 2024 P3 Q17 / L6","order":3056},
{"id":"p3-058","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Which buildings does the ECBC / Energy Conservation Act provision on buildings apply to?","back":"Commercial buildings with a connected load of 100 kW or more (or contract demand of 120 kVA or more).","explain":"ECBC compliance can be shown by the prescriptive approach, the trade-off approach (Envelope Performance Factor, EPF), or the whole-building performance approach using simulation. EPF compares the envelope of the proposed design against a baseline.","flash":false,"source":"BEE 2025 P3 Q6 / Q35","order":3057},
{"id":"p3-059","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What does the Solar Heat Gain Coefficient (SHGC) of a window measure?","back":"The fraction of incident solar radiation admitted through the fenestration as heat. For SHGC 0.25 and 600 W/m² incident, gain = 150 W/m².","explain":"A lower SHGC means less solar heat gain and lower cooling load. Visible Light Transmittance (VLT) measures daylight separately. Effective Aperture = VLT × Window-to-Wall Ratio. ECBC defines a skylight as fenestration sloped less than 60° from horizontal.","flash":false,"source":"BEE 2024 P3 Q15 / L6","order":3058},
{"id":"p3-060","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What is the difference between U-value, thermal emittance and solar reflectance (cool roof)?","back":"U-value = overall heat transfer coefficient through an assembly (W/m²K); lower means better insulation. Thermal emittance = a surface's ability to re-radiate absorbed heat. Solar reflectance = the fraction of sunlight reflected; high reflectance makes a cool roof.","explain":"Emissivity is the ratio of energy radiated by a material to that of a black body at the same temperature. Thermal bridging is a conductive path (e.g. through steel or concrete frames) that bypasses insulation. Thermal mass stores heat in building materials and delays peak loads.","flash":false,"source":"BEE 2025 P3 S-4 / BEE 2024 P3 S5","order":3059},
{"id":"p3-061","paper":3,"topic":"Fans & blowers","kind":"fact","front":"State the fan (and pump) affinity laws for a change in speed.","back":"Flow ∝ N; pressure (head) ∝ N²; power ∝ N³.","explain":"The same laws apply to speed changes made by VFD, pulley change or two-speed motors, and they assume the system curve passes through the origin (no static head). For fans the power also scales with air density. The cube law is why speed control saves so much more energy than damper throttling.","flash":true,"source":"BEE 2024 P3 Q6","order":3060},
{"id":"p3-062","paper":3,"topic":"Fans & blowers","kind":"fact","front":"By how much does fan power fall if the speed is reduced by 10%?","back":"About 27%, since 0.9³ = 0.729.","explain":"Similarly, 16 kW at 800 rpm falls to 16 × (600/800)³ = 6.75 kW at 600 rpm. Reducing a fan from 49 Hz to 34 Hz cuts power by about 1 − (34/49)³ ≈ 67%. A 52 kW fan would then save about 34.6 kW.","flash":true,"source":"BEE 2024 P3 Q19, Q20, Q50","order":3061},
{"id":"p3-063","paper":3,"topic":"Fans & blowers","kind":"fact","front":"What happens to fan airflow when system resistance increases (e.g. clogged filter, closed damper)?","back":"Airflow decreases: the operating point moves left along the fan curve to a higher pressure and lower flow.","explain":"The operating point is where the fan curve meets the system resistance curve (ΔP ∝ Q²). Larger ducts, smooth bends and clean filters reduce resistance. Dampers and filter fouling change the system curve; speed changes and inlet guide vanes change the fan curve.","flash":false,"source":"BEE 2024 P3 Q1 / BEE 2025 P3 Q27","order":3062},
{"id":"p3-064","paper":3,"topic":"Fans & blowers","kind":"fact","front":"Rank the common fan flow control methods by energy efficiency.","back":"Best to worst: speed control (VFD or variable speed coupling), then inlet guide vanes, then outlet damper throttling.","explain":"Throttling with a damper wastes energy across the damper while the fan stays at full speed. Inlet guide vanes pre-swirl the air and give moderate savings. VFDs follow the cube law, so they give the largest savings when flow is reduced substantially. Pulley changes suit permanent flow reductions.","flash":false,"source":"syllabus","order":3063},
{"id":"p3-065","paper":3,"topic":"Fans & blowers","kind":"fact","front":"How is fan static efficiency calculated from field measurements?","back":"η_static = (Q × ΔP_static) / (102 × shaft power), with Q in m³/s, ΔP in mmWC and power in kW.","explain":"Q is found by pitot traverse: velocity v = Cp × √(2g × Δp_velocity(mmWC) / ρ) m/s, then Q = v × duct area. Shaft power = motor input × motor efficiency (× gearbox or belt efficiency, if present). The constant 102 converts mmWC·m³/s to kW.","flash":false,"source":"BEE 2024 P3 L3","order":3064},
{"id":"p3-066","paper":3,"topic":"Fans & blowers","kind":"problem","front":"A centrifugal fan runs at 1480 rpm, delivering 36,000 m³/h at 350 mmWC and drawing 45 kW. Its speed is reduced to 1180 rpm with a VFD. Find the new flow, pressure, power and power saving (ignore VFD losses).","back":"Flow ≈ 28,700 m³/h; pressure ≈ 222 mmWC; power ≈ 22.8 kW; saving ≈ 22.2 kW.","explain":"The affinity laws give flow ∝ N, pressure ∝ N² and power ∝ N³. A 20% speed reduction halves the power. In real systems with significant static pressure, savings are somewhat lower than the pure cube law predicts.","steps":[{"prompt":"Find the speed ratio.","answer":"1180/1480 = 0.797","explain":"N2/N1."},{"prompt":"Find the new flow.","answer":"36,000 × 0.797 ≈ 28,700 m³/h","explain":"Q ∝ N."},{"prompt":"Find the new pressure.","answer":"350 × 0.797² ≈ 222 mmWC","explain":"P ∝ N²."},{"prompt":"Find the new power.","answer":"45 × 0.797³ ≈ 22.8 kW","explain":"kW ∝ N³."},{"prompt":"Find the saving.","answer":"45 − 22.8 ≈ 22.2 kW (≈ 49%)","explain":"Difference in input power."}],"flash":false,"source":"BEE 2024 P3 L3b (similar)","order":3065},
{"id":"p3-067","paper":3,"topic":"Pumps & pumping systems","kind":"fact","front":"What is the formula for the hydraulic (water) power of a pump?","back":"P_hydraulic (kW) = Q (m³/s) × H (m) × ρ (kg/m³) × g / 1000. Pump efficiency = hydraulic power ÷ shaft power.","explain":"Example: 200 m³/h at 30 m gives (200/3600) × 30 × 1000 × 9.81 / 1000 = 16.35 kW of hydraulic power. At 70% efficiency, input = 23.36 kW. Shaft power = motor input × motor efficiency.","flash":false,"source":"BEE 2024 P3 Q4","order":3066},
{"id":"p3-068","paper":3,"topic":"Pumps & pumping systems","kind":"fact","front":"If pump speed is reduced to two-thirds, what happens to power?","back":"Power falls to (2/3)³ ≈ 0.30, about 30% of the original, while flow falls to 67% and head to 44%.","explain":"This assumes a purely frictional system. Where a large static head exists, the pump may deliver much less flow (or none) at reduced speed, so check the system curve before relying on the cube law.","flash":false,"source":"BEE 2025 P3 Q20","order":3067},
{"id":"p3-069","paper":3,"topic":"Pumps & pumping systems","kind":"fact","front":"Why is a centrifugal pump impeller trimmed, and what happens to flow, head and power?","back":"To permanently reduce capacity to match the real system requirement (instead of throttling). Flow ∝ D, head ∝ D², power ∝ D³, so trimming reduces head.","explain":"Example: a 230 mm impeller delivering 150 m³/h, trimmed for 110 m³/h, becomes about 230 × 110/150 ≈ 169 mm. Trimming is irreversible and works best for small reductions (generally within about 10–20%). A VFD is preferred where demand varies.","flash":false,"source":"BEE 2024 P3 Q2, Q25 / BEE 2025 P3 Q29, Q39","order":3068},
{"id":"p3-070","paper":3,"topic":"Pumps & pumping systems","kind":"fact","front":"What is cavitation in a pump, and how is NPSH related to it?","back":"Cavitation is the formation and violent collapse of vapour bubbles when local pressure falls below vapour pressure. It erodes the impeller, causes noise and vibration, and reduces head. It is avoided when NPSH available exceeds NPSH required.","explain":"NPSHA rises with a higher suction-side liquid level, larger suction pipe diameter (less friction), shorter suction lines and cooler liquid. Increasing the suction pipe diameter therefore increases NPSHA. NPSHR is a property of the pump and rises with flow.","flash":false,"source":"BEE 2024 P3 Q3, Q5","order":3069},
{"id":"p3-071","paper":3,"topic":"Pumps & pumping systems","kind":"fact","front":"A pump designed for 40 lps at 20 m is operating at 16 m head. What happens to flow, efficiency and power?","back":"Flow rises above rated, efficiency falls (the pump has moved right of its BEP), and power drawn rises above rated.","explain":"On a centrifugal pump curve, lower head means higher flow. Moving away from the best efficiency point (BEP) on either side lowers efficiency. For most centrifugal pumps, power rises with flow, so the motor may also be overloaded.","flash":false,"source":"BEE 2024 P3 S3","order":3070},
{"id":"p3-072","paper":3,"topic":"Pumps & pumping systems","kind":"fact","front":"What is the efficiency of a centrifugal pump at shut-off head (zero flow)?","back":"0%: no useful hydraulic work is done, because Q = 0.","explain":"At shut-off, all the input power becomes heat in the liquid, which can overheat the pump. That is why minimum-flow recirculation lines are provided. Efficiency peaks at the BEP and falls to zero at both shut-off and run-out.","flash":false,"source":"BEE 2025 P3 Q38","order":3071},
{"id":"p3-073","paper":3,"topic":"Pumps & pumping systems","kind":"fact","front":"What are common symptoms of an oversized pump, and what is the best fix?","back":"A heavily throttled discharge valve, high pressure drop across the valve, high noise or vibration, and frequent bypass or recirculation. Fix it by trimming the impeller, fitting a smaller pump or impeller, or using a VFD, not by replacing only the motor or fitting a larger impeller.","explain":"Throttling wastes the excess head across the valve. If a pump runs at about 30% of rated flow, a correctly sized pump (or speed reduction) gives the largest saving. Larger diameter pipes also reduce friction head and system resistance.","flash":false,"source":"BEE 2025 P3 Q18, Q28 / BEE 2024 P3 Q7","order":3072},
{"id":"p3-074","paper":3,"topic":"Pumps & pumping systems","kind":"fact","front":"Why do VFD savings on pumps depend on the ratio of static head to friction head?","back":"Speed reduction must still overcome the fixed static head, so the cube-law saving is only achieved in friction-dominated systems. In static-head-dominated systems, savings are much smaller and efficiency drops.","explain":"The system curve is H = H_static + k·Q². When H_static is large, a small speed reduction moves the operating point far down the flow axis and away from the BEP. Always plot the pump curves at reduced speed against the actual system curve.","flash":false,"source":"syllabus","order":3073},
{"id":"p3-075","paper":3,"topic":"Pumps & pumping systems","kind":"problem","front":"A cooling water pump delivers 180 m³/h. Discharge pressure is 3.2 kg/cm² (about 32 m) and the suction lift is 3 m. The motor draws 28 kW at 90% efficiency. Find the pump efficiency. If the impeller (250 mm) is trimmed so the pump delivers 150 m³/h, estimate the new diameter and shaft power.","back":"Pump efficiency ≈ 68%; trimmed impeller ≈ 208 mm; new shaft power ≈ 14.6 kW.","explain":"Total head = discharge head + suction lift (if the source is below the pump), or discharge − suction head (if the source is above, i.e. flooded suction). Hydraulic power is ρgQH, and shaft power is motor input × motor efficiency. The impeller trim estimate uses the diameter affinity laws.","steps":[{"prompt":"Find the total head.","answer":"32 + 3 = 35 m","explain":"With a suction lift, add it to the discharge head."},{"prompt":"Find the hydraulic power.","answer":"(180/3600) × 35 × 9.81 = 17.17 kW","explain":"P = Q·H·ρ·g/1000 with ρ = 1000."},{"prompt":"Find the shaft power.","answer":"28 × 0.90 = 25.2 kW","explain":"Motor output = input × η_motor."},{"prompt":"Find the pump efficiency.","answer":"17.17 / 25.2 = 68.1%","explain":"η_pump = hydraulic / shaft power."},{"prompt":"Find the trimmed diameter and new power.","answer":"D2 = 250 × 150/180 ≈ 208 mm; P2 = 25.2 × (150/180)³ ≈ 14.6 kW","explain":"Q ∝ D, P ∝ D³."}],"flash":false,"source":"BEE 2024 P3 S6 / Q25 (similar)","order":3074},
{"id":"p3-076","paper":3,"topic":"Cooling towers","kind":"fact","front":"Define cooling tower range, approach and effectiveness.","back":"Range = hot water in − cold water out. Approach = cold water out − ambient wet bulb temperature. Effectiveness = range ÷ (range + approach).","explain":"Example: inlet 40°C, range 10°C, approach 5°C gives outlet 30°C and wet bulb 25°C. Approach (not the dry bulb) is the better indicator of tower performance; the lower the approach, the better. The wet bulb temperature is the theoretical lower limit for the cold water.","flash":true,"source":"BEE 2024 P3 Q9 / BEE 2025 P3 L-1","order":3075},
{"id":"p3-077","paper":3,"topic":"Cooling towers","kind":"fact","front":"What is the formula for cooling tower evaporation loss?","back":"Evaporation (m³/h) ≈ 0.00085 × 1.8 × circulation rate (m³/h) × range (°C).","explain":"Roughly 1% of circulating water is evaporated for every 7°C (about 5.5°C in some texts) of range. Evaporation is the useful cooling mechanism; drift (water carried out as droplets) and blowdown are the other losses.","flash":false,"source":"BEE 2024 P3 S7","order":3076},
{"id":"p3-078","paper":3,"topic":"Cooling towers","kind":"fact","front":"How are blowdown and make-up related to Cycles of Concentration (COC)?","back":"Blowdown = Evaporation ÷ (COC − 1). Make-up = Evaporation + Drift + Blowdown. For example, 12 m³/h evaporation at COC 2.5 needs 8 m³/h blowdown.","explain":"COC = dissolved solids in circulating water ÷ dissolved solids in make-up water, i.e. how many times water is reused before discharge. Raising COC (with better treatment) cuts blowdown and make-up, but risks scaling, corrosion and fouling.","flash":true,"source":"BEE 2025 P3 Q11 / L-1","order":3077},
{"id":"p3-079","paper":3,"topic":"Cooling towers","kind":"fact","front":"What is the most influential component of a cooling tower, and what does it do?","back":"The fill media: it increases water–air contact area and contact time for heat and mass transfer.","explain":"Splash fills break water into droplets. Film fills spread water into thin films and are more efficient, but they clog more easily with poor water quality. Clogged or damaged fill raises the approach directly.","flash":false,"source":"BEE 2025 P3 Q1, Q30","order":3078},
{"id":"p3-080","paper":3,"topic":"Cooling towers","kind":"fact","front":"If three of the four parameters (heat load, range, approach, wet bulb) are held constant, how does the required cooling tower size vary with the fourth?","back":"Directly with heat load; inversely with range; inversely with approach; inversely with wet bulb temperature.","explain":"A smaller approach demands a disproportionately larger tower. A higher range for the same approach and wet bulb means hotter inlet water and a bigger driving force, so a smaller tower suffices. A lower design wet bulb requires a larger tower.","flash":false,"source":"BEE 2025 P3 Q36","order":3079},
{"id":"p3-081","paper":3,"topic":"Cooling towers","kind":"fact","front":"List energy-saving measures for cooling towers.","back":"Clean and maintain fill and nozzles; use FRP blades and set the blade angle seasonally; fit VFDs or two-speed fans controlled on cold water temperature; maintain correct water chemistry and COC; balance flow across cells; avoid air recirculation and bypass.","explain":"Better tower performance lowers cold water temperature, which in turn cuts chiller or condenser energy. That system effect is often larger than the fan saving itself.","flash":false,"source":"BEE 2025 P3 Q31 / BEE 2024 P3 Q10","order":3080},
{"id":"p3-082","paper":3,"topic":"Cooling towers","kind":"problem","front":"A cooling tower circulates 1500 m³/h. Hot water is at 40°C, cold water at 32°C, and the ambient wet bulb is 28°C. Find the range, approach, effectiveness, heat rejected (TR), evaporation loss and blowdown at COC 4 (neglect drift).","back":"Range 8°C; approach 4°C; effectiveness 66.7%; ≈ 3968 TR; evaporation ≈ 18.4 m³/h; blowdown ≈ 6.1 m³/h; make-up ≈ 24.5 m³/h.","explain":"This combines every standard cooling-tower formula in one question. Evaporation uses the 0.00085 × 1.8 × flow × range rule, and blowdown follows from E/(COC − 1). Make-up replaces evaporation + blowdown (+ drift).","steps":[{"prompt":"Find the range and approach.","answer":"Range = 40 − 32 = 8°C; approach = 32 − 28 = 4°C","explain":"Definitions."},{"prompt":"Find the effectiveness.","answer":"8/(8 + 4) = 66.7%","explain":"Range/(range + approach)."},{"prompt":"Find the heat rejected.","answer":"1500 × 1000 × 8 = 1.2 × 10⁷ kcal/h; ÷ 3024 = 3968 TR","explain":"Q = m·cp·ΔT."},{"prompt":"Find the evaporation loss.","answer":"0.00085 × 1.8 × 1500 × 8 = 18.36 m³/h","explain":"BEE empirical formula."},{"prompt":"Find the blowdown and make-up.","answer":"B = 18.36/(4 − 1) = 6.12 m³/h; make-up = 18.36 + 6.12 = 24.48 m³/h","explain":"Blowdown = E/(COC − 1)."}],"flash":false,"source":"BEE 2025 P3 L-1 / BEE 2024 P3 S7 (similar)","order":3081},
{"id":"p3-083","paper":3,"topic":"Lighting","kind":"fact","front":"What is luminous efficacy, and what is its unit?","back":"The ratio of light output to electrical input, in lumens per watt (lm/W).","explain":"It is not the same as luminance (brightness of a surface, cd/m²) or illuminance (lux = lm/m²). Comparing efficacy, including control gear losses, is the basis for choosing an efficient lamp. LEDs offer high efficacy along with good colour rendering.","flash":false,"source":"BEE 2025 P3 Q3","order":3082},
{"id":"p3-084","paper":3,"topic":"Lighting","kind":"fact","front":"Is the lumen weighted most heavily towards blue light?","back":"No. The lumen is weighted by the eye's photopic sensitivity curve, which peaks in the green-yellow (about 555 nm), not blue.","explain":"That is why low-pressure sodium (monochromatic yellow) lamps have very high efficacy but render colour very poorly. The CRI scale runs to 100, where colours look identical to a reference source. Colour-critical tasks need lamps with high CRI.","flash":false,"source":"BEE 2024 P3 L1 / BEE 2025 P3 Q9","order":3083},
{"id":"p3-085","paper":3,"topic":"Lighting","kind":"fact","front":"What is the function of a luminaire?","back":"To distribute, control and direct the light from the lamp (plus housing, protecting and connecting it). It does not generate light itself.","explain":"Efficient luminaires with good optics and reflectors put more lumens on the working plane. That raises the utilisation factor and allows fewer lamps for the same illuminance.","flash":false,"source":"BEE 2024 P3 Q11 / BEE 2025 P3 Q34","order":3084}
]$cards$::jsonb);
